import { getCityByName } from "@/lib/data";
import { notFound } from "next/navigation";
import Image from "next/image";
import { PlaceHolderImages } from "@/lib/placeholder-images";
import { AttractionsTabs } from "@/components/city/AttractionsTabs";
import { findAttractions, type ApiAttraction } from "@/ai/flows/find-attractions";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { AlertCircle } from "lucide-react";

type CityPageProps = {
  params: {
    cityName: string;
  };
};

export default async function CityPage({ params }: CityPageProps) {
  // Fetch static city data
  const city = getCityByName(params.cityName);
  if (!city) {
    notFound();
  }
  const cityImage = PlaceHolderImages.find((img) => img.id === city.image);

  // Fetch real-time attractions from Google Places API
  const { attractions, error } = await findAttractions({ city: city.name });

  return (
    <div className="flex flex-col">
      <section className="relative h-[40vh] w-full flex items-end justify-start text-white p-8">
        {cityImage && (
          <Image
            src={cityImage.imageUrl}
            alt={cityImage.description}
            fill
            className="object-cover"
            priority
            data-ai-hint={cityImage.imageHint}
          />
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/40 to-transparent" />
        <div className="relative z-10">
          <h1 className="text-5xl md:text-6xl font-bold font-headline tracking-tight">
            {city.name}
          </h1>
          <p className="max-w-3xl text-lg text-neutral-200 mt-2">
            {city.description}
          </p>
        </div>
      </section>

      <section className="container mx-auto px-4 py-12">
        {error && (
           <Alert variant="destructive" className="mb-8">
             <AlertCircle className="h-4 w-4" />
             <AlertTitle>Error Fetching Attractions</AlertTitle>
             <AlertDescription>
              {error}
             </AlertDescription>
           </Alert>
        )}
        <AttractionsTabs attractions={attractions as ApiAttraction[]} />
      </section>
    </div>
  );
}
